	const batteryItem = batteryIndex >= 0 ? items[batteryIndex] : null;
	const panelWp = panelItem ? panelWattFrom(panelItem) : 0;
	const unitKwh = batteryItem ? batteryKwhFrom(batteryItem) : 0;
