	var LOC_PAGE_SIZE = 9;
	function locPages(total) {
		return Math.max(1, Math.ceil(total / LOC_PAGE_SIZE));
	}
	function govPage() {
		var mp = String(city || "").match(/^PG:(\d+)$/);
		var p = mp ? parseInt(mp[1], 10) : 1;
		return p >= 1 && p <= locPages(GOVS.length) ? p : 1;
	}
	function distParts() {
		return String(city || "").split("|");
	}
	function distPage(total) {
		var pp = parseInt(distParts()[2], 10);
		return pp >= 1 && pp <= locPages(total) ? pp : 1;
	}
	var LOC_TITLE = "";
	function locGovAsk(title) {
		if (title) LOC_TITLE = String(title);
		govPage();
		locPages(GOVS.length);
		return W((LOC_TITLE || " تحديد الموقع") + "\n" + SEP + "\n\nيرجى تحديد المحافظة التي يوجد فيها المشروع أو موقع التسليم.");
	}
	function locGovOtherAsk(remainingOnly) {
		var rows = [];
		for (var oi = 0; oi < GOVS.length; oi++) {
			var __gn = String(GOVS[oi].n || "");
			if (remainingOnly && (__gn === "صنعاء" || __gn === "عدن" || __gn === "صنعاء")) continue;
			rows.push({
				id: "gov_other_" + (oi + 1),
				title: __gn
			});
		}
		rows.push({
			id: "back_step",
			title: "العودة خطوة"
		});
		return {
			kind: "list",
			locList: true,
			button: "اختر المحافظة",
			sections: [{
				title: remainingOnly ? "باقي محافظات الجمهورية اليمنية" : "جميع محافظات الجمهورية اليمنية",
				rows
			}]
		};
	}
	function locDistAsk(gi) {
		var g = GOVS[gi - 1];
		var pg2 = distPage(g.d.length), tp2 = locPages(g.d.length);
		return W((LOC_TITLE || " تحديد الموقع") + "\n" + SEP + "\n\nاختر موقعك من القائمة بالأسفل._\n" + g.n + " ▸ المناطق" + (tp2 > 1 ? "\n_(صفحة " + pg2 + " من " + tp2 + " — اختر «عرض المزيد»)_" : "") + "\n\nأرسل 0 للعودة إلى البداية._");
	}
